function validate([m, n, indices]) {
  if (!Number.isInteger(m) || m < 1 || m > 50) return 'm is between 1 and 50.';
  if (!Number.isInteger(n) || n < 1 || n > 50) return 'n is between 1 and 50.';
  if (indices.length < 1 || indices.length > 100) return 'indices needs 1 to 100 entries.';
  for (const pair of indices) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each entry of indices is a pair [ri, ci].';
    const [r, c] = pair;
    if (!Number.isInteger(r) || r < 0 || r >= m) return 'Each ri is a row index from 0 to m - 1.';
    if (!Number.isInteger(c) || c < 0 || c >= n) return 'Each ci is a column index from 0 to n - 1.';
  }
  return null;
}

