function oddCells(m, n, indices) {
  const rows = new Array(m).fill(0);
  const cols = new Array(n).fill(0);

  for (const [r, c] of indices) {
    rows[r]++;
    cols[c]++;
  }

  let count = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if ((rows[i] + cols[j]) % 2 === 1) {
        count++;
      }
    }
  }
  return count;
}

