function oddCells(m, n, indices) {
  // Apply every increment to a real matrix, then count the odd cells.
  const grid = Array.from({ length: m }, () => new Array(n).fill(0));
  for (const [r, c] of indices) {
    for (let j = 0; j < n; j++) grid[r][j] += 1;
    for (let i = 0; i < m; i++) grid[i][c] += 1;
  }
  let odd = 0;
  for (const row of grid) for (const value of row) if (value % 2 !== 0) odd++;
  return odd;
}

