function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'large' ? int(40, 50) : int(1, 5);
  const n = size === 'large' ? int(40, 50) : int(1, 5);
  const k = size === 'large' ? int(90, 100) : int(1, 8);
  // Small row and column ranges make repeated rows and columns common.
  const rowSpan = int(1, m);
  const colSpan = int(1, n);
  const indices = Array.from({ length: k }, () => [int(0, rowSpan - 1), int(0, colSpan - 1)]);
  return [m, n, indices];
}
